// CSD_RATIONALE_BEGIN
// Attempt 65 regression (45.7%) vs attempt 61 (53.3%) was caused entirely by
// added anti-alias guidance clauses that confused the 4B model. Attempt 61's
// guidance is optimal for this model size.
//
// Remaining failures in attempt 61 (137/300 wrong) split into:
//   (a) mode_A 153 examples: syntax-valid but semantically wrong short SQL —
//       fundamental 4B model capability gap, not directly fixable via helpers.
//   (b) 1 repetition loop: model lists 792 schema columns endlessly, exhausting
//       the ~893-step Phase 3 budget (remaining-1 with no cap).
//
// Single targeted change: cap Phase 3 (RegenerateUnitOnGroundingFailure) at
// 300 steps instead of remaining-1 (≈893). This directly kills repetition loops
// that waste budget and runtime without hurting the 96%+ of queries that finish
// in under 100 steps (median 26, average 44.77 tokens). Freed budget is reallocated
// to Phase 4 CloseSpanWithinBudget (raised from 80 → 120 steps).
//
// All other parameters identical to attempt 61 (proven best):
// Phase 1: ≤5 unconstrained steps for "SQL: <<" preamble.
// Phase 2: OpenConstrainedSpan if not already inside.
// Phase 3: RegenerateUnitOnGroundingFailure (budget=min(remaining-1,300),
//           maxRetries=5, maxRollbackBudget=50).
// Phase 4: CloseConstrainedSpan if complete, else CloseSpanWithinBudget(120).
// Guidance: attempt 61's exact guidance string (no anti-alias additions).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the
//   implication is vacuous throughout. The only true-flip is via
//   RenderedEndsWith, at which point currentConstrainedOut := [] and
//   IsValidPrefix([]) holds by the method precondition. EOS break leaves
//   insideConstrainedOut false (implication vacuous).
//
// Phase 2 OpenConstrainedSpan: Runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by precondition.
//
// Phase 3 RegenerateUnitOnGroundingFailure: Postcondition guarantees
//   resultConstrained is always parser-valid. We assign
//   currentConstrainedOut := resultConstrained, re-establishing the invariant.
//   insideConstrainedOut is unchanged (still true from Phase 2 or entry).
//
// Phase 4a CloseConstrainedSpan: Sets insideConstrainedOut := false, making
//   the implication vacuously true; clears currentConstrainedOut := [].
//
// Phase 4b CloseSpanWithinBudget: Postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep +1 step; appends 0 (EOS) or 1 (non-EOS) token.
//   Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan +1 step, appends exactly 1 "<<" token. 1:1.
//
// Phase 3: stablePrefix = generated[..|generated| - |currentConstrainedOut|].
//   After assignment: |generated| = |stablePrefix| + |resultConstrained|
//     <= (|old_generated| - |currentConstrainedOut|) + sqlBudget
//     <= |old_generated| + sqlBudget
//     <= |generatedPrefix| + old_steps + sqlBudget = |generatedPrefix| + new_steps.
//   The bound |resultConstrained| <= sqlBudget follows from the helper's "at
//   most +budget token-steps" cost contract: each step produces at most one
//   visible token; rejected/rolled-back tokens consume budget without growing
//   resultConstrained. Cap sqlBudget := min(remaining-1, 300) ensures
//   sqlBudget <= remaining-1 <= maxSteps - old_steps - 1, so new_steps <= maxSteps.
//
// Phase 4a: CloseConstrainedSpan +1 step, appends at most 1 ">>" token. ≤1:1.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated|
//   + closeBudget; steps += closeBudget. Invariant preserved by transitivity.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded SQL via RegenerateUnitOnGroundingFailure
// Budget capped at 300 (vs uncapped remaining-1 ≈ 893 in attempt 61) to
// prevent runaway repetition loops that waste budget on schema-column lists.
// Typical Spider SQL is 26–80 tokens; cap of 300 covers even complex queries.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var sqlBudget: nat;
    if remaining - 1 <= 300 {
      sqlBudget := remaining - 1;
    } else {
      sqlBudget := 300;
    }
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, sqlBudget, 5, 50
    );
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

